<section x-show="activeTab==='vouchers'" x-cloak><h2>Your vouchers</h2><div class="wd-voucher-tabs">@foreach(['eligible'=>'Available','used'=>'Used','expired'=>'Unavailable'] as $key=>$label)<button @click="voucherSubTab='{{ $key }}'" :aria-pressed="voucherSubTab==='{{ $key }}'">{{ $label }} ({{ $voucherGroups['counts'][$key] }})</button>@endforeach</div>@if($couponStatus)<p role="status">{{ $couponStatus['message'] }}</p>@endif
<div class="wd-voucher-grid">@foreach($vouchers as $voucher)<article class="wd-voucher-card" x-show="voucherSubTab===@js($voucher['status'])"><span class="wd-perforation" aria-hidden="true"></span><div class="wd-voucher-value"><i data-lucide="ticket"></i>{{ $voucher['discountDisplay']??$voucher['title'] }}<small>OFF</small></div><div class="wd-voucher-copy"><h3>{{ $voucher['title'] }}</h3><p>{{ $voucher['description'] }}</p><p><strong class="wd-voucher-code">{{ $voucher['code'] }}</strong><button type="button" @click="navigator.clipboard.writeText(@js($voucher['code'])).then(()=>copiedVoucher=@js($voucher['code'])).catch(()=>appliedToast='Copy unavailable. Select the code to copy it.')" x-text="copiedVoucher===@js($voucher['code'])?'Copied':'Copy'">Copy</button></p><p>{{ $voucher['minSpendDisplay'] }}</p>@if(!empty($voucher['categoryRestriction']))<p>{{ $voucher['categoryRestriction'] }}</p>@endif @if($voucher['status']==='eligible')<button class="wd-primary" @disabled($preview) @click="applyVoucher(@js($voucher['code']))">Use voucher</button>@endif<details><summary>Terms &amp; conditions<i data-lucide="chevron-down"></i></summary><p>{{ $voucher['description'] }}</p><p>{{ $voucher['minSpendDisplay'] }}</p>@if(!empty($voucher['categoryRestriction']))<p>{{ $voucher['categoryRestriction'] }}</p>@endif</details></div></article>@endforeach</div>
@foreach(['eligible','used','expired'] as $key)@if($voucherGroups['counts'][$key]===0)<p x-show="voucherSubTab==='{{ $key }}'" class="wd-empty">No vouchers in this category.</p>@endif@endforeach
<form class="wd-manual-voucher" @submit.prevent="applyVoucher(couponInput)"><label for="wedding-voucher-code">Have a voucher code?</label><input id="wedding-voucher-code" x-model="couponInput" placeholder="Enter voucher code" required @disabled($preview)><button class="wd-primary" @disabled($preview)>Apply</button></form><p role="status" x-show="appliedToast" x-text="appliedToast"></p></section>
